import os, pty, subprocess, sys, select, time
# fake curl env
env=dict(os.environ); env["PATH"]="/tmp/fakebin:"+env["PATH"]
def run_combo(args, stdin_kind, stdout_kind, stderr_kind):
    # kinds: tty, pipe, devnull, file
    masters={}
    slaves={}
    def make(kind, for_stdout=False):
        if kind=="tty":
            m,s=pty.openpty()
            return m,s
        return None,None
    # subprocess stdin/out/err specification and readers
    proc_args={}
    fds_to_read=[]
    handles=[]
    # stdin
    stdin_m=stdin_s=None; stdout_m=stdout_s=None; stderr_m=stderr_s=None
    if stdin_kind=="tty":
        stdin_m, stdin_s=pty.openpty(); proc_args['stdin']=stdin_s
    elif stdin_kind=="pipe":
        proc_args['stdin']=subprocess.PIPE
    elif stdin_kind=="devnull":
        proc_args['stdin']=subprocess.DEVNULL
    elif stdin_kind=="file":
        f=open("/tmp/inputdata.txt","rb"); handles.append(f); proc_args['stdin']=f
    if stdout_kind=="tty":
        stdout_m, stdout_s=pty.openpty(); proc_args['stdout']=stdout_s
    elif stdout_kind=="pipe":
        proc_args['stdout']=subprocess.PIPE
    elif stdout_kind=="devnull":
        proc_args['stdout']=subprocess.DEVNULL
    if stderr_kind=="tty":
        stderr_m, stderr_s=pty.openpty(); proc_args['stderr']=stderr_s
    elif stderr_kind=="pipe":
        proc_args['stderr']=subprocess.PIPE
    open("/tmp/fakelog.txt","w").write("")
    open("/tmp/inputdata.txt","wb").write(b"FILEDATA")
    p=subprocess.Popen(["./executable"]+args, env=env, **proc_args)
    # close slave ends in parent
    for s in [stdin_s, stdout_s, stderr_s]:
        if s is not None: os.close(s)
    if stdin_kind=="pipe":
        p.stdin.write(b"PIPEDATA"); p.stdin.close()
    if stdin_kind=="tty":
        # don't write; curl won't read stdin unless -d@-; if it does fake curl cat would wait... need close master write? leave open but maybe EOF? To signal EOF close stdin_m after small?
        pass
    out=b""; err=b""
    # read using select for tty masters and pipes
    # simpler poll loop
    timeout=3; start=time.time()
    # set masters nonblocking
    import fcntl
    readers=[]
    if stdout_kind=="tty": readers.append(('out',stdout_m))
    if stderr_kind=="tty": readers.append(('err',stderr_m))
    for name,fd in readers:
        flags=fcntl.fcntl(fd, fcntl.F_GETFL); fcntl.fcntl(fd, fcntl.F_SETFL, flags|os.O_NONBLOCK)
    while time.time()-start<timeout:
        if p.poll() is not None:
            # drain a bit
            time.sleep(0.05)
            for name,fd in readers:
                try:
                    while True:
                        data=os.read(fd,4096)
                        if not data: break
                        if name=='out': out+=data
                        else: err+=data
                except BlockingIOError: pass
                except OSError: pass
            break
        for name,fd in readers:
            try:
                data=os.read(fd,4096)
                if data:
                    if name=='out': out+=data
                    else: err+=data
            except BlockingIOError: pass
            except OSError: pass
        time.sleep(0.02)
    else:
        p.kill()
        print("TIMEOUT")
    if stdout_kind=="pipe":
        try: out=p.stdout.read() or b""
        except: pass
    if stderr_kind=="pipe":
        try: err=p.stderr.read() or b""
        except: pass
    # close stdin master to unblock fake if needed
    if stdin_m is not None:
        try: os.close(stdin_m)
        except: pass
    try: p.wait(timeout=2)
    except: p.kill()
    for name,fd in readers:
        try: os.close(fd)
        except: pass
    log=open("/tmp/fakelog.txt","rb").read() if os.path.exists("/tmp/fakelog.txt") else b""
    curl_args=[l[4:-1].decode() for l in log.splitlines() if l.startswith(b'ARG<')]
    print(f"stdin={stdin_kind} stdout={stdout_kind} stderr={stderr_kind} args={args}")
    print(f"  curl={curl_args}")
    print(f"  out={out!r}")
    print(f"  err={err!r}")
    print(f"  fake stdin log tail={log!r}")
    print(f"  exit={p.returncode}")

# ensure fakebin exists (import probe creates it)
sys.path.insert(0,'/tmp'); import probe
for combo in [
 ("tty","pipe","pipe"),
 ("pipe","pipe","pipe"),
 ("devnull","pipe","pipe"),
 ("file","pipe","pipe"),
 ("tty","tty","pipe"),
 ("tty","pipe","tty"),
 ("pipe","tty","pipe"),
 ("tty","tty","tty"),
 ("devnull","tty","pipe"),
]:
    run_combo(["http://e.com"], *combo)
