import os,pty,subprocess,time,fcntl,json,sys
def run(args, out_kind='tty', err_kind='tty', in_kind='tty'):
    env=dict(os.environ); env['PATH']='/tmp/fakefd:'+env['PATH']
    ms={}
    kw={}
    slaves=[]
    for kind,name in [(in_kind,'stdin'),(out_kind,'stdout'),(err_kind,'stderr')]:
        if kind=='tty':
            m,s=pty.openpty(); ms[name]=m; kw[name]=s; slaves.append(s)
        elif kind=='pipe': kw[name]=subprocess.PIPE
        elif kind=='file':
            f=open(f'/tmp/{name}file','w+b'); kw[name]=f; ms[name]=f
    if os.path.exists('/tmp/fdinfo.json'): os.remove('/tmp/fdinfo.json')
    p=subprocess.Popen(['./executable']+args,env=env,**kw)
    for s in slaves: os.close(s)
    if in_kind=='pipe': p.stdin.close()
    # drain tty masters while wait
    outs={k:b'' for k in ms}
    start=time.time()
    for k,fd in ms.items():
        if isinstance(fd,int):
            fl=fcntl.fcntl(fd,fcntl.F_GETFL); fcntl.fcntl(fd,fcntl.F_SETFL,fl|os.O_NONBLOCK)
    while time.time()-start<3:
        for k,fd in ms.items():
            if isinstance(fd,int) and k!='stdin':
                try:
                    d=os.read(fd,4096)
                    if d: outs[k]+=d
                except: pass
        if p.poll() is not None: break
        time.sleep(0.02)
    time.sleep(0.05)
    for k,fd in ms.items():
        if isinstance(fd,int) and k!='stdin':
            try:
                while True:
                    d=os.read(fd,4096)
                    if not d: break
                    outs[k]+=d
            except: pass
    if out_kind=='pipe': outs['stdout']=p.stdout.read() or b''
    if err_kind=='pipe': outs['stderr']=p.stderr.read() or b''
    for k,fd in ms.items():
        if isinstance(fd,int):
            try: os.close(fd)
            except: pass
    try:p.wait(timeout=1)
    except:p.kill()
    info=json.load(open('/tmp/fdinfo.json')) if os.path.exists('/tmp/fdinfo.json') else None
    print(f"args={args} kinds={in_kind}/{out_kind}/{err_kind} child={info} out={outs} exit={p.returncode}")

for args in [["http://e.com"],["--pretty","http://e.com"],["--help"],["-v","http://e.com"]]:
    run(args,'tty','tty','tty')
    run(args,'pipe','pipe','pipe')
    run(args,'file','file','file')
