import os,pty,subprocess,time,fcntl,json,stat
def run(args, in_kind, out_kind='pipe', err_kind='pipe'):
    env=dict(os.environ); env['PATH']='/tmp/fakefd:'+env['PATH']
    kw={}; closers=[]; masters={}; parentinfo={}
    # stdin
    if in_kind=='tty':
        m,s=pty.openpty(); kw['stdin']=s; masters['stdin']=m; closers.append(s); parentinfo['stdin']=os.fstat(s).st_ino
    elif in_kind=='pipe':
        r,w=os.pipe(); kw['stdin']=r; closers.append(r); masters['stdinw']=w; parentinfo['stdin']=os.fstat(r).st_ino
    elif in_kind=='file':
        f=open('/tmp/stdinfiledata','w+b'); f.write(b'hello'); f.seek(0); kw['stdin']=f; masters['stdinfile']=f; parentinfo['stdin']=os.fstat(f.fileno()).st_ino
    elif in_kind=='devnull':
        kw['stdin']=subprocess.DEVNULL
    # stdout
    if out_kind=='tty':
        m,s=pty.openpty(); kw['stdout']=s; masters['stdout']=m; closers.append(s); parentinfo['stdout']=os.fstat(s).st_ino
    elif out_kind=='pipe': kw['stdout']=subprocess.PIPE
    elif out_kind=='file':
        f=open('/tmp/stdoutfiledata','w+b'); kw['stdout']=f; masters['stdoutfile']=f; parentinfo['stdout']=os.fstat(f.fileno()).st_ino
    # stderr
    if err_kind=='tty':
        m,s=pty.openpty(); kw['stderr']=s; masters['stderr']=m; closers.append(s); parentinfo['stderr']=os.fstat(s).st_ino
    elif err_kind=='pipe': kw['stderr']=subprocess.PIPE
    elif err_kind=='file':
        f=open('/tmp/stderrfiledata','w+b'); kw['stderr']=f; masters['stderrfile']=f; parentinfo['stderr']=os.fstat(f.fileno()).st_ino
    if os.path.exists('/tmp/fdinfo.json'): os.remove('/tmp/fdinfo.json')
    p=subprocess.Popen(['./executable']+args,env=env,**kw)
    for s in closers:
        try: os.close(s)
        except: pass
    if 'stdinw' in masters:
        os.write(masters['stdinw'],b'hello'); os.close(masters['stdinw'])
    # drain tty
    start=time.time(); outs={}
    for k in ['stdout','stderr']:
        if k in masters and isinstance(masters[k],int):
            fd=masters[k]; fl=fcntl.fcntl(fd,fcntl.F_GETFL); fcntl.fcntl(fd,fcntl.F_SETFL,fl|os.O_NONBLOCK); outs[k]=b''
    while time.time()-start<3:
        for k in outs:
            try:
                d=os.read(masters[k],4096)
                if d: outs[k]+=d
            except: pass
        if p.poll() is not None: break
        time.sleep(0.02)
    if out_kind=='pipe': outs['stdout']=p.stdout.read() or b''
    if err_kind=='pipe': outs['stderr']=p.stderr.read() or b''
    for k,v in list(masters.items()):
        if isinstance(v,int):
            try: os.close(v)
            except: pass
    try:p.wait(timeout=1)
    except:p.kill()
    info=json.load(open('/tmp/fdinfo.json')) if os.path.exists('/tmp/fdinfo.json') else None
    def typ(x):
        return 'tty' if x['isatty'] else ('fifo' if x['is_fifo'] else ('reg' if x['is_reg'] else ('chr' if x['is_chr'] else '?')))
    ct={k:(typ(v),v['ino']) for k,v in info.items()} if info else None
    print(f"args={args} in={in_kind} out={out_kind} err={err_kind} parent={parentinfo} child={ct} outs={outs}")
