    for fd in masters.values():
        try:os.close(fd)
        except:pass
    try:p.wait(timeout=1)
    except:p.kill()
    print(f"args={args} in={in_kind} out={out_kind} err={err_kind} => stdout={outs.get('stdout')!r} stderr={outs.get('stderr')!r}")

