func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return errno == 0
}

func contains(args []string, s string) bool {
	for _, a := range args {
		if a == s {
			return true
		}
	}
	return false
}

func parseURL(s string) string {
	hadHTTPPrefix := strings.HasPrefix(s, "http")
	if !hadHTTPPrefix {
		s = "http://" + s
	}
	println(s)
	u, err := url.Parse(s)
	if err != nil {
		fmt.Print(err)
		return s
	}
	if u.Host == ":" {
		u.Host = "localhost"
	} else if strings.HasPrefix(u.Host, ":") {
		u.Host = "localhost" + u.Host
	}
	ret := u.String()
	if !hadHTTPPrefix {
		ret = strings.TrimPrefix(ret, "http://")
		ret = strings.TrimPrefix(ret, "//")
	}
	return ret
}

// classify a request item by the first separator occurring in it.
// kind: 0 none, 1 header, 2 query, 3 data string, 4 raw JSON data
func classifyItem(item string) (kind int, idx int) {
	for i := 0; i < len(item); i++ {
		if strings.HasPrefix(item[i:], ":=") {
			return 4, i
		}
		if strings.HasPrefix(item[i:], "==") {
			return 2, i
		}
		if item[i] == ':' {
			return 1, i
		}
		if item[i] == '=' {
			return 3, i
		}
	}
	return 0, -1
}

func programName() string {
	if len(os.Args) > 0 && os.Args[0] != "" {
		return os.Args[0]
	}
	return "curlie"
}

// usageWriter replaces the first occurrence of the curl usage fragment in
// each individual Write, matching the reference behaviour.
type usageWriter struct {
	out io.Writer
}

func (w *usageWriter) Write(p []byte) (int, error) {
	repl := []byte(programName() + " [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]")
	p2 := bytes.Replace(p, []byte("curl [options...] <url>"), repl, 1)
	_, _ = w.out.Write(p2)
	return len(p), nil
}

var binaryNote = []byte("+-----------------------------------------+\n| NOTE: binary data not shown in terminal |\n+-----------------------------------------+\n")

type stdoutPrettyWriter struct {
	out           io.Writer
	binary        bool
	decided       bool
	jsonMode      bool
	depth         int
	inString      bool
	isValue       bool
	valuePending  bool
	prev          byte
	hasPrev       bool
	suppressReset bool
}

func (w *stdoutPrettyWriter) writeIndent(buf *bytes.Buffer) {
	for i := 0; i < w.depth; i++ {
		buf.WriteString("    ")
	}
}

func (w *stdoutPrettyWriter) Write(p []byte) (int, error) {
	origLen := len(p)
	if w.binary {
		return origLen, nil
	}
	if bytes.IndexByte(p, 0) >= 0 {
		w.binary = true
		p = binaryNote
	}
	if len(p) == 0 {
		return origLen, nil
	}
	if !w.decided {
		w.decided = true
		w.jsonMode = p[0] == '{' || p[0] == '['
	}
	if !w.jsonMode {
		_, _ = w.out.Write(p)
		return origLen, nil
	}
	w.suppressReset = p[0] == '}' || p[0] == ']'
	var buf bytes.Buffer
	for _, b := range p {
		if w.inString {
			buf.WriteByte(b)
			if b == '"' && (!w.hasPrev || w.prev != '\\') {
				w.inString = false
			}
			w.prev = b
			w.hasPrev = true
			continue
		}
		switch b {
		case ' ', '\t', '\r', '\n':
			// Skip JSON whitespace outside strings.
		case '{', '[':
			w.valuePending = false
			w.isValue = false
			buf.WriteString("\x1b[37m")
			buf.WriteByte(b)
			w.depth++
			buf.WriteByte('\n')
			w.writeIndent(&buf)
		case '}', ']':
			w.valuePending = false
			w.depth--
			buf.WriteByte('\n')
			w.writeIndent(&buf)
			buf.WriteString("\x1b[37m")
			buf.WriteByte(b)
			if w.depth <= 0 && !w.suppressReset {
				buf.WriteString("\n\x1b[0m")
			}
		case ',':
			w.valuePending = false
			w.isValue = false
			buf.WriteString("\x1b[37m")
			buf.WriteByte(b)
			buf.WriteByte('\n')
			w.writeIndent(&buf)
		case ':':
			w.valuePending = true
			w.isValue = true
			buf.WriteString("\x1b[37m: ")
		case '"':
			if w.hasPrev && w.prev == '\\' {
				buf.WriteByte(b)
			} else {
				if w.isValue {
					buf.WriteString("\x1b[36m")
				} else {
					buf.WriteString("\x1b[34m")
				}
				buf.WriteByte(b)
				w.inString = true
				w.valuePending = false
			}
		default:
			if w.valuePending {
				if b == 'n' || b == 't' || b == 'f' {
					buf.WriteString("\x1b[35m")
				} else {
					buf.WriteString("\x1b[36m")
				}
				w.valuePending = false
			}
			buf.WriteByte(b)
		}
		w.prev = b
		w.hasPrev = true
	}
	_, _ = w.out.Write(buf.Bytes())
	return origLen, nil
}

var (
	reInfo     = regexp.MustCompile(`^\* `)
	reCurlErr  = regexp.MustCompile(`^curl: \([0-9]+\)`)
	reResponse = regexp.MustCompile(`^(HTTP)/([0-9.]+\s+[0-9]{3})(\s.+)$`)
	reRequest  = regexp.MustCompile(`^([A-Z]+)(\s+\S+\s+)(HTTP)/([0-9.]+\s*)$`)
	reHeader   = regexp.MustCompile(`^([A-Za-z0-9.\-]*:)(.*)$`)
)

func colorizeStderrLine(s string) (string, bool) {
	if reInfo.MatchString(s) {
		return "\x1b[90m" + s + "\x1b[0m", true
	}
	if reCurlErr.MatchString(s) {
		return "\x1b[31m" + s + "\x1b[0m", true
	}
	if m := reResponse.FindStringSubmatch(s); m != nil {
		return "\x1b[34m" + m[1] + "\x1b[37m/" + "\x1b[36m" + m[2] + "\x1b[33m" + m[3] + "\x1b[0m", true
	}
	if m := reRequest.FindStringSubmatch(s); m != nil {
		return "\x1b[34m" + m[1] + "\x1b[37m" + m[2] + "\x1b[34m" + m[3] + "\x1b[37m/" + "\x1b[36m" + m[4] + "\x1b[0m", true
	}
	if m := reHeader.FindStringSubmatch(s); m != nil {
		return "\x1b[37m" + m[1] + "\x1b[36m" + m[2] + "\x1b[0m", true
	}
	return s, false
}

type stderrWriter struct {
	out     io.Writer
	pretty  bool
	verbose bool
	buf     []byte
}

func (w *stderrWriter) Write(p []byte) (int, error) {
	w.buf = append(w.buf, p...)
	for {
		idx := bytes.IndexByte(w.buf, '\n')
		if idx < 0 {
			break
		}
		line := make([]byte, idx+1)
		copy(line, w.buf[:idx+1])
		w.buf = w.buf[idx+1:]
		w.processLine(line)
	}
	return len(p), nil
}

func (w *stderrWriter) processLine(line []byte) {
	if len(line) == 0 {
		return
	}
	var content []byte
	switch line[0] {
	case '*':
		if !w.verbose {
			return
		}
		content = line
	case '>':
		if !w.verbose {
			return
		}
		if len(line) >= 2 {
			content = line[2:]
		} else {
			content = nil
		}
	case '<':
		if len(line) >= 2 {
			content = line[2:]
		} else {
			content = nil
		}
	case '{', '}':
		if !w.verbose {
			return
		}
		_, _ = w.out.Write([]byte("\n\n"))
		return
	default:
		content = line
	}
	if w.pretty && len(content) > 0 {
		hasNL := content[len(content)-1] == '\n'
		body := content
		if hasNL {
			body = content[:len(content)-1]
		}
		if colored, ok := colorizeStderrLine(string(body)); ok {
			_, _ = io.WriteString(w.out, colored)
			if hasNL {
				_, _ = w.out.Write([]byte("\n"))
			}
			return
		}
	}
	_, _ = w.out.Write(content)
}

func main() {
	os.Exit(run())
}

func run() int {
	rawArgs := os.Args[1:]

	// First pass: curlie's form mode is selected by exact --form / -F tokens
	// anywhere in the original argument list.
	form := false
	{
		filtered := make([]string, 0, len(rawArgs))
		for _, a := range rawArgs {
			if a == "--form" || a == "-F" {
				form = true
				continue
			}
			filtered = append(filtered, a)
		}
		rawArgs = filtered
	}

	// Parse curl options (which may be interspersed) and positionals.
	var options []string
	var positionals []string
	afterDashDash := false
	for i := 0; i < len(rawArgs); {
		arg := rawArgs[i]
		i++
		if !afterDashDash && arg == "--" {
			afterDashDash = true
			continue
		}
		if !afterDashDash && len(arg) > 1 && arg[0] == '-' {
			if arg[1] == '-' {
				options = append(options, arg)
				if !strings.Contains(arg, "=") {
					name := strings.TrimPrefix(arg[2:], "expand-")
					if longOptsWithValue[name] && i < len(rawArgs) {
						options = append(options, rawArgs[i])
						i++
					}
				}
				continue
			}
			// Short-option cluster, processed byte-by-byte.
			for j := 1; j < len(arg); j++ {
				ch := arg[j]
				options = append(options, "-"+arg[j:j+1])
				if shortOptsWithValue[ch] {
					if j+1 < len(arg) {
						options = append(options, arg[j+1:])
					} else if i < len(rawArgs) {
						options = append(options, rawArgs[i])
						i++
					}
					break
				}
			}
			continue
		}
		positionals = append(positionals, arg)
	}

	// [METHOD] URL [ITEM ...]
	method := ""
	hasMethod := false
	pidx := 0
	if len(positionals) > 0 {
		up := strings.ToUpper(positionals[0])
		if methods[up] {
			method = up
			hasMethod = true
			pidx = 1
		}
	}
	urlStr := ""
	hasURL := false
	if pidx < len(positionals) {
		urlStr = positionals[pidx]
		hasURL = true
		pidx++
	}
	items := []string(nil)
	if pidx < len(positionals) {
		items = positionals[pidx:]
	}

	// Request items.
	jsonData := make(map[string]interface{})
	var itemTokens []string
	urlWithQuery := urlStr
	for _, item := range items {
		kind, idx := classifyItem(item)
		switch kind {
		case 1: // header
			itemTokens = append(itemTokens, "-H", item)
		case 2: // query
			key := item[:idx]
			val := item[idx+2:]
			sep := "?"
			if strings.Contains(urlWithQuery, "?") {
				sep = "&"
			}
			urlWithQuery += sep + url.QueryEscape(key) + "=" + url.QueryEscape(val)
		case 3: // data string
			if form {
				itemTokens = append(itemTokens, "-F", item)
			} else {
				jsonData[item[:idx]] = item[idx+1:]
			}
		case 4: // raw JSON data
			var v interface{}
			_ = json.Unmarshal([]byte(item[idx+2:]), &v)
			jsonData[item[:idx]] = v
		default:
			itemTokens = append(itemTokens, item)
		}
	}

	curlURL := ""
	if hasURL {
		curlURL = parseURL(urlWithQuery)
	}

	// Assemble the initial curl argument list.
	var args []string
	args = append(args, options...)
	if hasMethod {
		if method == "HEAD" {
			args = append(args, "-I")
		} else {
			args = append(args, "-X", method)
		}
	}
	args = append(args, itemTokens...)
	if len(jsonData) > 0 {
		data, _ := json.Marshal(jsonData)
		args = append(args, "-d", string(data))
	}
	if hasURL {
		args = append(args, curlURL)
	}

	// Second pass over the assembled list: extract curlie tokens. This is
	// deliberately a blind token scan (option values are not excluded).
	printCurl := false
	explicitPretty := false
	{
		filtered := make([]string, 0, len(args))
		for _, a := range args {
			switch a {
			case "--curl":
				printCurl = true
			case "--pretty":
				explicitPretty = true
			case "-i":
				// dropped
			default:
				filtered = append(filtered, a)
			}
		}
		args = filtered
	}

	// The no-argument help case.
	if len(args) == 0 && !printCurl {
		finalArgs := []string{"-h", "all", "-H", "Accept: application/json, */*"}
		return execute(finalArgs, true, false, false, false, false)
	}

	hasHelp := contains(args, "-h") || contains(args, "--help")
	userVerbose := contains(args, "-v") || contains(args, "--verbose")
	hasD := contains(args, "-d")
	hasF := contains(args, "-F")
	hasCT := false
	hasAccept := false
	for i := 0; i+1 < len(args); i++ {
		if args[i] == "-H" || args[i] == "--header" {
			v := args[i+1]
			if len(v) >= len("content-type:") && strings.EqualFold(v[:len("content-type:")], "content-type:") {
				hasCT = true
			}
			if len(v) >= len("accept:") && strings.EqualFold(v[:len("accept:")], "accept:") {
				hasAccept = true
			}
		}
	}

	stdoutPretty := (explicitPretty || isTerminal(os.Stdout.Fd())) && !hasHelp
	stderrPretty := (explicitPretty || isTerminal(os.Stderr.Fd())) && !hasHelp
	stdinIsTerm := isTerminal(os.Stdin.Fd())

	finalArgs := append([]string{}, args...)
	finalArgs = append(finalArgs, "-s", "-S")
	if stderrPretty {
		finalArgs = append(finalArgs, "-v")
	}
	stdinAdded := false
	if !hasHelp && !stdinIsTerm && !hasD {
		finalArgs = append(finalArgs, "-d@-")
		stdinAdded = true
	}
	if !hasHelp && (hasD || stdinAdded) && !hasCT && !hasF {
		finalArgs = append(finalArgs, "-H", "Content-Type: application/json")
	}
	if !hasAccept {
		finalArgs = append(finalArgs, "-H", "Accept: application/json, */*")
	}

	if printCurl {
		quoted := make([]string, len(finalArgs))
		for i, a := range finalArgs {
			if strings.Contains(a, " ") {
				a = strconv.Quote(a)
			}
			quoted[i] = a
		}
		fmt.Println("curl " + strings.Join(quoted, " "))
		return 0
	}

	return execute(finalArgs, hasHelp, userVerbose, stdoutPretty, stderrPretty, stdinAdded)
}

func execute(finalArgs []string, hasHelp, userVerbose, stdoutPretty, stderrPretty, stdinAdded bool) int {
	cmd := exec.Command("curl", finalArgs...)
	if stdinAdded {
		// Deliberately not an *os.File, so the child receives a pipe.
		cmd.Stdin = struct{ io.Reader }{os.Stdin}
	} else {
		cmd.Stdin = os.Stdin
	}
	seWriter := &stderrWriter{out: os.Stderr, pretty: stderrPretty, verbose: userVerbose}
	cmd.Stderr = seWriter
	if hasHelp {
		cmd.Stdout = &usageWriter{out: os.Stdout}
	} else if stdoutPretty {
		cmd.Stdout = &stdoutPrettyWriter{out: os.Stdout}
	} else {
		cmd.Stdout = os.Stdout
	}
	err := cmd.Run()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return exitErr.ExitCode()
		}
		if stderrPretty {
			// Route through the line writer; an unterminated line is
			// consequently never emitted, as in the reference.
			_, _ = fmt.Fprint(seWriter, err)
		} else {
			_, _ = fmt.Fprint(os.Stderr, err)
		}
	}
	return 0
}
