open('/tmp/fake_err.bin','wb').write(b'* info\n> POST / HTTP/1.1\n> A: b\n> \n} [9 bytes data]\n< HTTP/1.1 200 OK\n< A: b\ncurl: (7) x\n')
open('/tmp/fake_code.txt','w').write('0')
def run_one(binpath,args,in_kind,out_kind,err_kind):
    env=dict(os.environ); env['PATH']='/tmp/fakeio:'+env['PATH']
    kw={}; masters={}; slaves=[]; files={}
    for name,kind in [('stdin',in_kind),('stdout',out_kind),('stderr',err_kind)]:
        if kind=='tty':
            m,s=pty.openpty(); masters[name]=m; slaves.append(s); kw[name]=s
        elif kind=='pipe': kw[name]=subprocess.PIPE
        elif kind=='file':
            f=open(f'/tmp/pty_{name}.dat','w+b'); files[name]=f; kw[name]=f
            if name=='stdin': f.write(b'STDINDATA'); f.seek(0)
        elif kind=='devnull': kw[name]=subprocess.DEVNULL
    p=subprocess.Popen(['./executable']+args,executable=binpath,env=env,**kw)
    for s in slaves: os.close(s)
    if in_kind=='pipe':
        p.stdin.write(b'STDINDATA'); p.stdin.close()
    outs={}
    for name,fd in masters.items():
        if name=='stdin': continue
        fl=fcntl.fcntl(fd,fcntl.F_GETFL); fcntl.fcntl(fd,fcntl.F_SETFL,fl|os.O_NONBLOCK); outs[name]=b''
    start=time.time()
    while time.time()-start<3:
        for name in list(outs):
            try:
                d=os.read(masters[name],4096)
                if d: outs[name]+=d
            except: pass
        if p.poll() is not None:
            time.sleep(0.03)
            for name in list(outs):
                try:
                    while True:
                        d=os.read(masters[name],4096)
                        if not d: break
                        outs[name]+=d
                except: pass
            break
        time.sleep(0.01)
    if out_kind=='pipe': outs['stdout']=p.stdout.read() or b''
    if err_kind=='pipe': outs['stderr']=p.stderr.read() or b''
    for name,f in files.items():
        if name!='stdin': f.seek(0); outs[name]=f.read()
        f.close()
    for fd in masters.values():
        try:os.close(fd)
        except:pass
    try:p.wait(timeout=1)
    except:p.kill(); p.wait()
    return p.returncode,outs.get('stdout'),outs.get('stderr')

