import struct
for fn in ['doc/get.png','doc/put.png']:
 data=open(fn,'rb').read(); print(fn,len(data),data[:8]); pos=8
 while pos<len(data):
  ln=struct.unpack('>I',data[pos:pos+4])[0]; typ=data[pos+4:pos+8]; chunk=data[pos+8:pos+8+ln]
  print(typ,ln, chunk[:100] if typ in [b'tEXt',b'iTXt',b'zTXt',b'IHDR'] else b'')
  pos+=12+ln
  if typ==b'IEND': break
PY"}

